window.PRACTICE={"levels": [{"id": "D1", "name": "Level 1 · Python basics", "sub": "print, variables, numbers, text"}, {"id": "D2", "name": "Level 2 · Decisions", "sub": "if, elif, else and sensor rules"}, {"id": "D3", "name": "Level 3 · Loops and lists", "sub": "looping through readings"}, {"id": "D4", "name": "Level 4 · Text, CSV and dictionaries", "sub": "parsing serial lines and counting"}, {"id": "D5", "name": "Level 5 · Functions and statistics", "sub": "mean, median, spread, scaling"}, {"id": "D6", "name": "Level 6 · Cleaning sensor data", "sub": "filters, outliers, gaps, map()"}, {"id": "D7", "name": "Level 7 · Mini projects", "sub": "a whole data pipeline"}, {"id": "D8", "name": "Level 8 · Daylight Tracker (CA3)", "sub": "labels, percent, spec 7.1, hours of light, energy saved"}], "challenges": [{"level": "D1", "id": "hello", "title": "Say hello to your data", "goal": "Print exactly <code>Light sensor ready</code> on one line.", "starter": "# Use print() to show text.\n", "tests": "check(\"printed the message\",\"Light sensor ready\" in OUT.splitlines(),\"output was: \"+repr(OUT))", "solution": "print(\"Light sensor ready\")\n", "hints": ["print() shows text. Put the text inside quotes."], "topic": ""}, {"level": "D1", "id": "fstring_reading", "title": "Report a reading", "goal": "<code>raw = 442</code> and <code>percent = 32</code> are set. Print <code>Raw ADC: 442 | Light %: 32%</code> using an f-string.", "starter": "raw = 442\npercent = 32\n# print one f-string line\n", "tests": "check(\"printed the line\",\"Raw ADC: 442 | Light %: 32%\" in OUT.splitlines(),\"output was: \"+repr(OUT))", "solution": "raw = 442\npercent = 32\nprint(f\"Raw ADC: {raw} | Light %: {percent}%\")\n", "hints": ["f-strings start with f before the quote.", "Put variables in { }. The % sign after {percent} is just text."], "topic": ""}, {"level": "D1", "id": "convert_text", "title": "Text to number", "goal": "The serial port gave the text <code>text = \"688\"</code>. Make <code>raw = int(text)</code> and <code>is_dark = raw &gt; 500</code>.", "starter": "text = \"688\"\n# raw = \n# is_dark = \n", "tests": "check(\"raw is the number 688\",S.get(\"raw\")==688 and isinstance(S.get(\"raw\"),int),repr(S.get(\"raw\")))\ncheck(\"is_dark is True\",S.get(\"is_dark\") is True,repr(S.get(\"is_dark\")))", "solution": "text = \"688\"\nraw = int(text)\nis_dark = raw > 500\n", "hints": ["int(text) turns text into a number.", "A comparison like raw > 500 gives True or False."], "topic": ""}, {"level": "D1", "id": "mean3", "title": "Mean of three", "goal": "Three readings are set: <code>a = 420</code>, <code>b = 450</code>, <code>c = 441</code>. Calculate <code>mean</code> and round it to 1 decimal place.", "starter": "a = 420\nb = 450\nc = 441\n# mean = \n", "tests": "check(\"mean is 437.0\",S.get(\"mean\")==437.0,repr(S.get(\"mean\")))", "solution": "a = 420\nb = 450\nc = 441\nmean = round((a + b + c) / 3, 1)\n", "hints": ["mean = total ÷ how many.", "Use round(value, 1)."], "topic": ""}, {"level": "D1", "id": "map_by_hand", "title": "map() by hand", "goal": "The Arduino line is <code>map(raw, 650, 0, 0, 100)</code>. For <code>raw = 325</code> calculate <code>percent</code> with the formula <code>(raw - 650) * (100 - 0) / (0 - 650) + 0</code>, then make it a whole number with <code>int()</code>.", "starter": "raw = 325\n# percent = \n", "tests": "check(\"percent is 50\",S.get(\"percent\")==50,repr(S.get(\"percent\")))", "solution": "raw = 325\npercent = int((raw - 650) * (100 - 0) / (0 - 650) + 0)\n", "hints": ["Type the formula exactly as given.", "int() cuts off decimals like Arduino does."], "topic": ""}, {"level": "D1", "id": "share", "title": "Percentage share", "goal": "<code>dark = 27</code> readings out of <code>total = 90</code>. Calculate <code>share</code> as a percentage rounded to 1 decimal place.", "starter": "dark = 27\ntotal = 90\n# share = \n", "tests": "check(\"share is 30.0\",S.get(\"share\")==30.0,repr(S.get(\"share\")))", "solution": "dark = 27\ntotal = 90\nshare = round(dark / total * 100, 1)\n", "hints": ["share = part ÷ whole × 100"], "topic": ""}, {"level": "D2", "id": "classify_light", "title": "Classify the light", "goal": "Write <code>classify_light(raw)</code> with the kit thresholds: above 500 is <code>\"DARK\"</code>, above 300 <code>\"DIM\"</code>, above 100 <code>\"BRIGHT\"</code>, otherwise <code>\"VERY BRIGHT\"</code> (remember: a low raw value means bright).", "starter": "def classify_light(raw):\n    pass\n", "tests": "t(\"classify_light(688)\", lambda: S[\"classify_light\"](688), 'DARK')\nt(\"classify_light(501)\", lambda: S[\"classify_light\"](501), 'DARK')\nt(\"classify_light(500)\", lambda: S[\"classify_light\"](500), 'DIM')\nt(\"classify_light(301)\", lambda: S[\"classify_light\"](301), 'DIM')\nt(\"classify_light(300)\", lambda: S[\"classify_light\"](300), 'BRIGHT')\nt(\"classify_light(101)\", lambda: S[\"classify_light\"](101), 'BRIGHT')\nt(\"classify_light(100)\", lambda: S[\"classify_light\"](100), 'VERY BRIGHT')\nt(\"classify_light(0)\", lambda: S[\"classify_light\"](0), 'VERY BRIGHT')", "solution": "def classify_light(raw):\n    if raw > 500:\n        return \"DARK\"\n    elif raw > 300:\n        return \"DIM\"\n    elif raw > 100:\n        return \"BRIGHT\"\n    else:\n        return \"VERY BRIGHT\"\n", "hints": ["Test the biggest threshold first.", "if / elif / elif / else with return in each."], "topic": "Lab 1"}, {"level": "D2", "id": "is_valid", "title": "Is the reading believable?", "goal": "Write <code>is_valid(raw)</code>. A reading is valid when it is a number from 5 to 1000 <em>including both</em>. A floating wire gives 0 or 4095 and must be rejected. Text such as <code>\"ERR\"</code> or <code>None</code> is also invalid.", "starter": "def is_valid(raw):\n    pass\n", "tests": "t(\"is_valid(688)\", lambda: S[\"is_valid\"](688), True)\nt(\"is_valid(5)\", lambda: S[\"is_valid\"](5), True)\nt(\"is_valid(1000)\", lambda: S[\"is_valid\"](1000), True)\nt(\"is_valid(4)\", lambda: S[\"is_valid\"](4), False)\nt(\"is_valid(1001)\", lambda: S[\"is_valid\"](1001), False)\nt(\"is_valid(4095)\", lambda: S[\"is_valid\"](4095), False)\nt(\"is_valid(0)\", lambda: S[\"is_valid\"](0), False)\nt(\"is_valid('ERR')\", lambda: S[\"is_valid\"]('ERR'), False)\nt(\"is_valid(None)\", lambda: S[\"is_valid\"](None), False)", "solution": "def is_valid(raw):\n    if not isinstance(raw, (int, float)):\n        return False\n    return 5 <= raw <= 1000\n", "hints": ["Check the type first: isinstance(raw, (int, float))", "Chained comparison: 5 <= raw <= 1000"], "topic": "Lab 2"}, {"level": "D2", "id": "led_colour", "title": "Corridor light colour", "goal": "From your Criterion B product: <code>led_colour(percent)</code> returns <code>\"RED\"</code> below 30 (too dark, lights ON), <code>\"YELLOW\"</code> from 30 to 59, and <code>\"GREEN\"</code> from 60 up.", "starter": "def led_colour(percent):\n    pass\n", "tests": "t(\"led_colour(0)\", lambda: S[\"led_colour\"](0), 'RED')\nt(\"led_colour(29)\", lambda: S[\"led_colour\"](29), 'RED')\nt(\"led_colour(30)\", lambda: S[\"led_colour\"](30), 'YELLOW')\nt(\"led_colour(59)\", lambda: S[\"led_colour\"](59), 'YELLOW')\nt(\"led_colour(60)\", lambda: S[\"led_colour\"](60), 'GREEN')\nt(\"led_colour(100)\", lambda: S[\"led_colour\"](100), 'GREEN')", "solution": "def led_colour(percent):\n    if percent < 30:\n        return \"RED\"\n    elif percent < 60:\n        return \"YELLOW\"\n    return \"GREEN\"\n", "hints": ["Smallest first: below 30, then below 60, else GREEN."], "topic": "Lab 1"}, {"level": "D2", "id": "needs_light", "title": "Lights on?", "goal": "Write <code>needs_light(percent, occupied)</code>: return True only when it is dark (below 30) <strong>and</strong> someone is there (<code>occupied</code> is True).", "starter": "def needs_light(percent, occupied):\n    pass\n", "tests": "t(\"needs_light(10, True)\", lambda: S[\"needs_light\"](10, True), True)\nt(\"needs_light(10, False)\", lambda: S[\"needs_light\"](10, False), False)\nt(\"needs_light(50, True)\", lambda: S[\"needs_light\"](50, True), False)\nt(\"needs_light(29, True)\", lambda: S[\"needs_light\"](29, True), True)\nt(\"needs_light(30, True)\", lambda: S[\"needs_light\"](30, True), False)", "solution": "def needs_light(percent, occupied):\n    return percent < 30 and occupied\n", "hints": ["Use and to need both."], "topic": ""}, {"level": "D2", "id": "battery_state", "title": "Battery state", "goal": "Write <code>battery_state(volts)</code>: <code>\"LOW\"</code> below 3.3, <code>\"OK\"</code> from 3.3 up to but not including 4.0, and <code>\"FULL\"</code> at 4.0 or more.", "starter": "def battery_state(volts):\n    pass\n", "tests": "t(\"battery_state(3.0)\", lambda: S[\"battery_state\"](3.0), 'LOW')\nt(\"battery_state(3.29)\", lambda: S[\"battery_state\"](3.29), 'LOW')\nt(\"battery_state(3.3)\", lambda: S[\"battery_state\"](3.3), 'OK')\nt(\"battery_state(3.99)\", lambda: S[\"battery_state\"](3.99), 'OK')\nt(\"battery_state(4.0)\", lambda: S[\"battery_state\"](4.0), 'FULL')\nt(\"battery_state(4.2)\", lambda: S[\"battery_state\"](4.2), 'FULL')", "solution": "def battery_state(volts):\n    if volts < 3.3:\n        return \"LOW\"\n    elif volts < 4.0:\n        return \"OK\"\n    return \"FULL\"\n", "hints": ["Same shape as led_colour."], "topic": ""}, {"level": "D3", "id": "total", "title": "Total of readings", "goal": "Write <code>total(values)</code> that adds up a list <strong>using a loop</strong> (do not use sum()).", "starter": "def total(values):\n    pass\n", "tests": "t(\"total([3, 4, 5])\", lambda: S[\"total\"]([3, 4, 5]), 12)\nt(\"total([])\", lambda: S[\"total\"]([]), 0)\nt(\"total([10])\", lambda: S[\"total\"]([10]), 10)\nt(\"total([1.5, 2.5])\", lambda: S[\"total\"]([1.5, 2.5]), 4.0)\ncheck(\"uses a loop\",\"for \" in SRC,\"use a for loop\")", "solution": "def total(values):\n    answer = 0\n    for v in values:\n        answer += v\n    return answer\n", "hints": ["Start with answer = 0, then add each value."], "topic": ""}, {"level": "D3", "id": "count_above", "title": "Count above a threshold", "goal": "Write <code>count_above(values, limit)</code> that returns how many values are <em>greater than</em> limit.", "starter": "def count_above(values, limit):\n    pass\n", "tests": "t(\"count_above([1, 5, 9, 5], 5)\", lambda: S[\"count_above\"]([1, 5, 9, 5], 5), 1)\nt(\"count_above([], 3)\", lambda: S[\"count_above\"]([], 3), 0)\nt(\"count_above([10, 20, 30], 0)\", lambda: S[\"count_above\"]([10, 20, 30], 0), 3)\nt(\"count_above([4, 4, 4], 4)\", lambda: S[\"count_above\"]([4, 4, 4], 4), 0)", "solution": "def count_above(values, limit):\n    n = 0\n    for v in values:\n        if v > limit:\n            n += 1\n    return n\n", "hints": ["Add one to a counter when the test is true."], "topic": ""}, {"level": "D3", "id": "biggest", "title": "Find the biggest", "goal": "Write <code>biggest(values)</code> with a loop (no max()). Return <code>None</code> for an empty list.", "starter": "def biggest(values):\n    pass\n", "tests": "t(\"biggest([3, 9, 2])\", lambda: S[\"biggest\"]([3, 9, 2]), 9)\nt(\"biggest([])\", lambda: S[\"biggest\"]([]), None)\nt(\"biggest([-5, -2, -9])\", lambda: S[\"biggest\"]([-5, -2, -9]), -2)\nt(\"biggest([7])\", lambda: S[\"biggest\"]([7]), 7)\ncheck(\"no max()\",\"max(\" not in SRC,\"loop instead of max()\")", "solution": "def biggest(values):\n    if not values:\n        return None\n    best = values[0]\n    for v in values:\n        if v > best:\n            best = v\n    return best\n", "hints": ["Start with best = values[0]; update it when you see a bigger value."], "topic": ""}, {"level": "D3", "id": "running_max", "title": "Running maximum", "goal": "Write <code>running_max(values)</code> that returns a list where each item is the biggest value seen so far. <code>[3, 1, 4, 2, 5]</code> gives <code>[3, 3, 4, 4, 5]</code>.", "starter": "def running_max(values):\n    pass\n", "tests": "t(\"running_max([3, 1, 4, 2, 5])\", lambda: S[\"running_max\"]([3, 1, 4, 2, 5]), [3, 3, 4, 4, 5])\nt(\"running_max([])\", lambda: S[\"running_max\"]([]), [])\nt(\"running_max([5, 4, 3])\", lambda: S[\"running_max\"]([5, 4, 3]), [5, 5, 5])", "solution": "def running_max(values):\n    out = []\n    best = None\n    for v in values:\n        if best is None or v > best:\n            best = v\n        out.append(best)\n    return out\n", "hints": ["Keep best outside the loop and append it every time."], "topic": ""}, {"level": "D3", "id": "moving_average", "title": "Moving average", "goal": "Write <code>moving_average(values, window)</code>. Item i is the mean of the last <code>window</code> values up to i (fewer at the start), rounded to 1 decimal. This is <code>rolling(window, min_periods=1).mean()</code> from the kit script.", "starter": "def moving_average(values, window):\n    pass\n", "tests": "t(\"moving_average([10, 20, 30, 40, 50], 3)\", lambda: S[\"moving_average\"]([10, 20, 30, 40, 50], 3), [10.0, 15.0, 20.0, 30.0, 40.0])\nt(\"moving_average([5], 5)\", lambda: S[\"moving_average\"]([5], 5), [5.0])\nt(\"moving_average([], 3)\", lambda: S[\"moving_average\"]([], 3), [])\nt(\"moving_average([1, 2, 3, 4], 2)\", lambda: S[\"moving_average\"]([1, 2, 3, 4], 2), [1.0, 1.5, 2.5, 3.5])", "solution": "def moving_average(values, window):\n    out = []\n    for i in range(len(values)):\n        part = values[max(0, i - window + 1): i + 1]\n        out.append(round(sum(part) / len(part), 1))\n    return out\n", "hints": ["values[max(0, i - window + 1): i + 1] is the window.", "Divide the sum by len(part), not by window."], "topic": "Lab 2"}, {"level": "D3", "id": "countdown_list", "title": "Build a list", "goal": "Write <code>every_nth(values, n)</code> that returns every n-th item starting with the first. <code>every_nth([1,2,3,4,5,6,7], 3)</code> gives <code>[1, 4, 7]</code>.", "starter": "def every_nth(values, n):\n    pass\n", "tests": "t(\"every_nth([1, 2, 3, 4, 5, 6, 7], 3)\", lambda: S[\"every_nth\"]([1, 2, 3, 4, 5, 6, 7], 3), [1, 4, 7])\nt(\"every_nth([1, 2, 3], 1)\", lambda: S[\"every_nth\"]([1, 2, 3], 1), [1, 2, 3])\nt(\"every_nth([], 2)\", lambda: S[\"every_nth\"]([], 2), [])", "solution": "def every_nth(values, n):\n    return values[::n]\n", "hints": ["Slicing has a step: values[start:stop:step]"], "topic": ""}, {"level": "D3", "id": "count_dark_runs", "title": "Count dark spells", "goal": "Write <code>dark_spells(readings)</code>. <code>readings</code> is a list of condition names. Count how many separate runs of consecutive <code>\"DARK\"</code> there are. <code>[\"DARK\",\"DARK\",\"DIM\",\"DARK\"]</code> has 2.", "starter": "def dark_spells(readings):\n    pass\n", "tests": "t(\"dark_spells(['DARK', 'DARK', 'DIM', 'DARK'])\", lambda: S[\"dark_spells\"](['DARK', 'DARK', 'DIM', 'DARK']), 2)\nt(\"dark_spells([])\", lambda: S[\"dark_spells\"]([]), 0)\nt(\"dark_spells(['DIM', 'DIM'])\", lambda: S[\"dark_spells\"](['DIM', 'DIM']), 0)\nt(\"dark_spells(['DARK', 'DARK', 'DARK'])\", lambda: S[\"dark_spells\"](['DARK', 'DARK', 'DARK']), 1)\nt(\"dark_spells(['DARK', 'DIM', 'DARK', 'DIM', 'DARK'])\", lambda: S[\"dark_spells\"](['DARK', 'DIM', 'DARK', 'DIM', 'DARK']), 3)", "solution": "def dark_spells(readings):\n    n = 0\n    previous = None\n    for r in readings:\n        if r == \"DARK\" and previous != \"DARK\":\n            n += 1\n        previous = r\n    return n\n", "hints": ["A new spell starts when this reading is DARK and the previous one was not."], "topic": ""}, {"level": "D4", "id": "parse_line", "title": "Parse a serial line", "goal": "The kit's <code>parse_ldr_line(line)</code>: from <code>\"Raw ADC: 420  |  Light %: 35%  |  Condition: DIM  (indoor shade)\"</code> return <code>(420, 35, \"DIM\")</code>. A damaged line returns <code>(None, None, None)</code>.", "starter": "def parse_ldr_line(line):\n    pass\n", "tests": "t(\"parse_ldr_line('Raw ADC: 420  |  Light %: 35%  |  Condition: DIM  (indoor shade or twilight)')\", lambda: S[\"parse_ldr_line\"]('Raw ADC: 420  |  Light %: 35%  |  Condition: DIM  (indoor shade or twilight)'), (420, 35, 'DIM'))\nt(\"parse_ldr_line('Raw ADC: 20  |  Light %: 97%  |  Condition: VERY BRIGHT (direct sunlight)')\", lambda: S[\"parse_ldr_line\"]('Raw ADC: 20  |  Light %: 97%  |  Condition: VERY BRIGHT (direct sunlight)'), (20, 97, 'VERY BRIGHT'))\nt(\"parse_ldr_line('garbage')\", lambda: S[\"parse_ldr_line\"]('garbage'), (None, None, None))\nt(\"parse_ldr_line('Raw ADC: ERR | Light %: 5% | Condition: DARK')\", lambda: S[\"parse_ldr_line\"]('Raw ADC: ERR | Light %: 5% | Condition: DARK'), (None, None, None))", "solution": "def parse_ldr_line(line):\n    try:\n        parts = line.split(\"|\")\n        if len(parts) >= 3:\n            raw = int(parts[0].replace(\"Raw ADC:\", \"\").strip())\n            pct = int(parts[1].replace(\"Light %:\", \"\").replace(\"%\", \"\").strip())\n            cond = parts[2].replace(\"Condition:\", \"\").strip().split(\"(\")[0].strip()\n            return raw, pct, cond\n    except (ValueError, IndexError):\n        pass\n    return None, None, None\n", "hints": ["split('|') cuts the line into parts. replace() removes labels. strip() removes spaces.", "Wrap the conversions in try / except ValueError."], "topic": "Lab 2"}, {"level": "D4", "id": "split_csv_row", "title": "Split a CSV row", "goal": "Write <code>split_csv_row(line)</code>: given <code>\"2026-10-13 15:06:27,688,0,DARK\"</code> return <code>[\"2026-10-13 15:06:27\", 688, 0, \"DARK\"]</code> (numbers as ints).", "starter": "def split_csv_row(line):\n    pass\n", "tests": "t(\"split_csv_row('2026-10-13 15:06:27,688,0,DARK')\", lambda: S[\"split_csv_row\"]('2026-10-13 15:06:27,688,0,DARK'), ['2026-10-13 15:06:27', 688, 0, 'DARK'])\nt(\"split_csv_row('t,5,99,VERY BRIGHT')\", lambda: S[\"split_csv_row\"]('t,5,99,VERY BRIGHT'), ['t', 5, 99, 'VERY BRIGHT'])", "solution": "def split_csv_row(line):\n    a, b, c, d = line.strip().split(\",\")\n    return [a, int(b), int(c), d]\n", "hints": ["line.split(',') gives 4 pieces.", "Convert the 2nd and 3rd with int()."], "topic": ""}, {"level": "D4", "id": "csv_to_dicts", "title": "CSV text to dictionaries", "goal": "Write <code>csv_to_dicts(text)</code>. The first line is the header. Return a list of dictionaries, one per data row, with the header words as keys and <em>text</em> values. Ignore blank lines.", "starter": "def csv_to_dicts(text):\n    pass\n", "tests": "t(\"two rows\", lambda: S[\"csv_to_dicts\"](\"A,B\\n1,2\\n3,4\\n\"), [{\"A\":\"1\",\"B\":\"2\"},{\"A\":\"3\",\"B\":\"4\"}])\nt(\"blank lines ignored\", lambda: S[\"csv_to_dicts\"](\"X\\n\\n5\\n\\n\"), [{\"X\":\"5\"}])\nt(\"header only\", lambda: S[\"csv_to_dicts\"](\"X,Y\"), [])", "solution": "def csv_to_dicts(text):\n    lines = [l for l in text.splitlines() if l.strip()]\n    if not lines:\n        return []\n    header = lines[0].split(\",\")\n    return [dict(zip(header, l.split(\",\"))) for l in lines[1:]]\n", "hints": ["text.splitlines() gives the lines.", "dict(zip(header, values)) builds one row."], "topic": "Lab 2"}, {"level": "D4", "id": "count_conditions", "title": "Count each condition", "goal": "Write <code>count_conditions(readings)</code> that returns a dictionary of how many times each name appears.", "starter": "def count_conditions(readings):\n    pass\n", "tests": "t(\"count_conditions(['DARK', 'DIM', 'DARK'])\", lambda: S[\"count_conditions\"](['DARK', 'DIM', 'DARK']), {'DARK': 2, 'DIM': 1})\nt(\"count_conditions([])\", lambda: S[\"count_conditions\"]([]), {})\nt(\"count_conditions(['A'])\", lambda: S[\"count_conditions\"](['A']), {'A': 1})", "solution": "def count_conditions(readings):\n    counts = {}\n    for r in readings:\n        counts[r] = counts.get(r, 0) + 1\n    return counts\n", "hints": ["counts[r] = counts.get(r, 0) + 1"], "topic": "Lab 2"}, {"level": "D4", "id": "most_common", "title": "Most common condition", "goal": "Write <code>most_common(readings)</code>: return the name that appears most often. If the list is empty return <code>None</code>. (Ties: return any of them.)", "starter": "def most_common(readings):\n    pass\n", "tests": "t(\"DARK wins\",lambda:S[\"most_common\"]([\"DARK\",\"DIM\",\"DARK\"]),\"DARK\")\nt(\"empty\",lambda:S[\"most_common\"]([]),None)\nt(\"single\",lambda:S[\"most_common\"]([\"X\"]),\"X\")\ncheck(\"tie returns one of them\",S[\"most_common\"]([\"A\",\"B\"]) in (\"A\",\"B\"),\"\")", "solution": "def most_common(readings):\n    counts = {}\n    for r in readings:\n        counts[r] = counts.get(r, 0) + 1\n    if not counts:\n        return None\n    return max(counts, key=counts.get)\n", "hints": ["Count first, then max(counts, key=counts.get)."], "topic": ""}, {"level": "D4", "id": "percent_share", "title": "Share of each condition", "goal": "Write <code>percent_share(counts)</code>: from <code>{\"DARK\": 3, \"DIM\": 1}</code> return <code>{\"DARK\": 75.0, \"DIM\": 25.0}</code> (percent, 1 decimal).", "starter": "def percent_share(counts):\n    pass\n", "tests": "t(\"percent_share({'DARK': 3, 'DIM': 1})\", lambda: S[\"percent_share\"]({'DARK': 3, 'DIM': 1}), {'DARK': 75.0, 'DIM': 25.0})\nt(\"percent_share({'A': 1, 'B': 2})\", lambda: S[\"percent_share\"]({'A': 1, 'B': 2}), {'A': 33.3, 'B': 66.7})", "solution": "def percent_share(counts):\n    total = sum(counts.values())\n    return {k: round(v / total * 100, 1) for k, v in counts.items()}\n", "hints": ["total = sum(counts.values())"], "topic": "Lab 2"}, {"level": "D4", "id": "clean_text", "title": "Tidy a condition word", "goal": "Sensors and people are untidy. Write <code>tidy(text)</code>: remove spaces at both ends, make it UPPER case, and turn inner double spaces into single spaces. <code>\"  very  bright \"</code> becomes <code>\"VERY BRIGHT\"</code>.", "starter": "def tidy(text):\n    pass\n", "tests": "t(\"tidy('  very  bright ')\", lambda: S[\"tidy\"]('  very  bright '), 'VERY BRIGHT')\nt(\"tidy('dim')\", lambda: S[\"tidy\"]('dim'), 'DIM')\nt(\"tidy('  DARK')\", lambda: S[\"tidy\"]('  DARK'), 'DARK')", "solution": "def tidy(text):\n    return \" \".join(text.split()).upper()\n", "hints": ["text.split() with no argument splits on any spaces and drops extras.", "\" \".join(list) puts them back with one space."], "topic": ""}, {"level": "D5", "id": "mean", "title": "Mean", "goal": "Write <code>mean(values)</code> (no statistics module). Return <code>None</code> for an empty list.", "starter": "def mean(values):\n    pass\n", "tests": "t(\"mean([1, 2, 3])\", lambda: S[\"mean\"]([1, 2, 3]), 2.0)\nt(\"mean([10])\", lambda: S[\"mean\"]([10]), 10.0)\nt(\"mean([])\", lambda: S[\"mean\"]([]), None)\nt(\"mean([1.5, 2.5])\", lambda: S[\"mean\"]([1.5, 2.5]), 2.0)", "solution": "def mean(values):\n    if not values:\n        return None\n    return sum(values) / len(values)\n", "hints": ["sum(values) / len(values)"], "topic": ""}, {"level": "D5", "id": "median", "title": "Median", "goal": "Write <code>median(values)</code>: the middle value after sorting; for an even count, the mean of the two middle values. Empty list gives <code>None</code>.", "starter": "def median(values):\n    pass\n", "tests": "t(\"median([3, 1, 2])\", lambda: S[\"median\"]([3, 1, 2]), 2)\nt(\"median([4, 1, 3, 2])\", lambda: S[\"median\"]([4, 1, 3, 2]), 2.5)\nt(\"median([5])\", lambda: S[\"median\"]([5]), 5)\nt(\"median([])\", lambda: S[\"median\"]([]), None)\nt(\"median([50, 51, 250, 49, 52])\", lambda: S[\"median\"]([50, 51, 250, 49, 52]), 51)", "solution": "def median(values):\n    if not values:\n        return None\n    s = sorted(values)\n    n = len(s)\n    mid = n // 2\n    if n % 2:\n        return s[mid]\n    return (s[mid - 1] + s[mid]) / 2\n", "hints": ["sorted() first. Odd length: s[n // 2]. Even: average the two middle ones."], "topic": ""}, {"level": "D5", "id": "std_dev", "title": "Standard deviation", "goal": "Write <code>std_dev(values)</code>: the <strong>sample</strong> standard deviation (divide by n - 1), the same as pandas and <code>statistics.stdev</code>. Fewer than 2 values gives <code>0.0</code>. Round to 2 decimals.", "starter": "def std_dev(values):\n    pass\n", "tests": "t(\"std_dev([2, 4, 4, 4, 5, 5, 7, 9])\", lambda: S[\"std_dev\"]([2, 4, 4, 4, 5, 5, 7, 9]), 2.14)\nt(\"std_dev([5, 5, 5])\", lambda: S[\"std_dev\"]([5, 5, 5]), 0.0)\nt(\"std_dev([1])\", lambda: S[\"std_dev\"]([1]), 0.0)\nt(\"std_dev([])\", lambda: S[\"std_dev\"]([]), 0.0)\nt(\"std_dev([10, 20])\", lambda: S[\"std_dev\"]([10, 20]), 7.07)", "solution": "def std_dev(values):\n    n = len(values)\n    if n < 2:\n        return 0.0\n    m = sum(values) / n\n    var = sum((v - m) ** 2 for v in values) / (n - 1)\n    return round(var ** 0.5, 2)\n", "hints": ["variance = sum of (v - mean)² divided by (n - 1).", "Square root is ** 0.5"], "topic": ""}, {"level": "D5", "id": "value_range", "title": "Range of the data", "goal": "Write <code>value_range(values)</code> that returns the tuple <code>(smallest, biggest)</code>. Empty list gives <code>(None, None)</code>.", "starter": "def value_range(values):\n    pass\n", "tests": "t(\"value_range([3, 9, 2])\", lambda: S[\"value_range\"]([3, 9, 2]), (2, 9))\nt(\"value_range([5])\", lambda: S[\"value_range\"]([5]), (5, 5))\nt(\"value_range([])\", lambda: S[\"value_range\"]([]), (None, None))", "solution": "def value_range(values):\n    if not values:\n        return None, None\n    return min(values), max(values)\n", "hints": ["Return two values separated by a comma."], "topic": ""}, {"level": "D5", "id": "normalise", "title": "Scale to 0–1", "goal": "Write <code>normalise(values)</code> (min-max scaling): <code>(v - low) / (high - low)</code> for each value, rounded to 3 decimals. If every value is the same return a list of 0.0.", "starter": "def normalise(values):\n    pass\n", "tests": "t(\"normalise([0, 5, 10])\", lambda: S[\"normalise\"]([0, 5, 10]), [0.0, 0.5, 1.0])\nt(\"normalise([2, 4, 6, 10])\", lambda: S[\"normalise\"]([2, 4, 6, 10]), [0.0, 0.25, 0.5, 1.0])\nt(\"normalise([3, 3])\", lambda: S[\"normalise\"]([3, 3]), [0.0, 0.0])\nt(\"normalise([])\", lambda: S[\"normalise\"]([]), [])", "solution": "def normalise(values):\n    if not values:\n        return []\n    low, high = min(values), max(values)\n    if high == low:\n        return [0.0 for _ in values]\n    return [round((v - low) / (high - low), 3) for v in values]\n", "hints": ["Guard against dividing by zero when high == low."], "topic": ""}, {"level": "D5", "id": "z_scores", "title": "Z-scores", "goal": "Write <code>z_scores(values)</code>: for each value return <code>(v - mean) / sd</code> using the <strong>sample</strong> standard deviation, rounded to 2 decimals. If sd is 0 return zeros.", "starter": "def z_scores(values):\n    pass\n", "tests": "t(\"z_scores([1, 2, 3])\", lambda: S[\"z_scores\"]([1, 2, 3]), [-1.0, 0.0, 1.0])\nt(\"z_scores([5, 5])\", lambda: S[\"z_scores\"]([5, 5]), [0.0, 0.0])\nt(\"z_scores([10, 20, 30, 40])\", lambda: S[\"z_scores\"]([10, 20, 30, 40]), [-1.16, -0.39, 0.39, 1.16])", "solution": "def z_scores(values):\n    n = len(values)\n    if n < 2:\n        return [0.0 for _ in values]\n    m = sum(values) / n\n    sd = (sum((v - m) ** 2 for v in values) / (n - 1)) ** 0.5\n    if sd == 0:\n        return [0.0 for _ in values]\n    return [round((v - m) / sd, 2) for v in values]\n", "hints": ["Mean first, then sd, then each (v - mean) / sd."], "topic": "Lab 2"}, {"level": "D5", "id": "correlation", "title": "How related are two lists?", "goal": "Write <code>correlation(xs, ys)</code> (Pearson r) rounded to 2 decimals. Use it to compare light % and raw ADC: they should be strongly negative. If either list has no spread return <code>0.0</code>.", "starter": "def correlation(xs, ys):\n    pass\n", "tests": "t(\"correlation([1, 2, 3], [2, 4, 6])\", lambda: S[\"correlation\"]([1, 2, 3], [2, 4, 6]), 1.0)\nt(\"correlation([1, 2, 3], [3, 2, 1])\", lambda: S[\"correlation\"]([1, 2, 3], [3, 2, 1]), -1.0)\nt(\"correlation([1, 2, 3], [5, 5, 5])\", lambda: S[\"correlation\"]([1, 2, 3], [5, 5, 5]), 0.0)\nt(\"correlation([1, 2, 3, 4], [1, 3, 2, 4])\", lambda: S[\"correlation\"]([1, 2, 3, 4], [1, 3, 2, 4]), 0.8)", "solution": "def correlation(xs, ys):\n    n = len(xs)\n    mx, my = sum(xs) / n, sum(ys) / n\n    sxx = sum((x - mx) ** 2 for x in xs)\n    syy = sum((y - my) ** 2 for y in ys)\n    if sxx == 0 or syy == 0:\n        return 0.0\n    sxy = sum((x - mx) * (y - my) for x, y in zip(xs, ys))\n    return round(sxy / (sxx * syy) ** 0.5, 2)\n", "hints": ["r = Σ(x-mx)(y-my) ÷ √(Σ(x-mx)² · Σ(y-my)²)"], "topic": ""}, {"level": "D6", "id": "filter_range", "title": "Range filter", "goal": "Write <code>filter_range(values, low, high)</code>: keep only values from low to high including both, in the same order.", "starter": "def filter_range(values, low, high):\n    pass\n", "tests": "t(\"filter_range([51, 4095, 50, 0, 52], 5, 1000)\", lambda: S[\"filter_range\"]([51, 4095, 50, 0, 52], 5, 1000), [51, 50, 52])\nt(\"filter_range([], 0, 10)\", lambda: S[\"filter_range\"]([], 0, 10), [])\nt(\"filter_range([5, 1000], 5, 1000)\", lambda: S[\"filter_range\"]([5, 1000], 5, 1000), [5, 1000])", "solution": "def filter_range(values, low, high):\n    return [v for v in values if low <= v <= high]\n", "hints": ["A list comprehension with an if."], "topic": "Lab 2"}, {"level": "D6", "id": "drop_missing", "title": "Drop missing values", "goal": "Write <code>drop_missing(rows)</code>: <code>rows</code> is a list of lists. Remove any row that contains <code>None</code> or an empty string <code>\"\"</code>.", "starter": "def drop_missing(rows):\n    pass\n", "tests": "t(\"drop_missing([[1, 2], [3, None], [None, None], [5, 6]])\", lambda: S[\"drop_missing\"]([[1, 2], [3, None], [None, None], [5, 6]]), [[1, 2], [5, 6]])\nt(\"drop_missing([[1, ''], ['a', 'b']])\", lambda: S[\"drop_missing\"]([[1, ''], ['a', 'b']]), [['a', 'b']])\nt(\"drop_missing([])\", lambda: S[\"drop_missing\"]([]), [])", "solution": "def drop_missing(rows):\n    return [r for r in rows if None not in r and \"\" not in r]\n", "hints": ["None not in r tests the whole row at once."], "topic": "Lab 2"}, {"level": "D6", "id": "remove_outliers", "title": "Remove outliers (z-score)", "goal": "Write <code>remove_outliers(values, limit=3.0)</code>: drop every value whose absolute z-score (sample sd) is <strong>limit or more</strong>. If sd is 0 keep everything. Keep the original order.", "starter": "def remove_outliers(values, limit=3.0):\n    pass\n", "tests": "base=[50]*10+[51]*10\nt(\"keeps normal data\",lambda:S[\"remove_outliers\"](base),base)\nt(\"drops a huge spike\",lambda:S[\"remove_outliers\"](base+[4000]),base)\nt(\"tight limit\",lambda:S[\"remove_outliers\"]([10,10,10,10,30],1.5),[10,10,10,10])\nt(\"no spread\",lambda:S[\"remove_outliers\"]([7,7,7]),[7,7,7])\nt(\"tiny list\",lambda:S[\"remove_outliers\"]([5]),[5])", "solution": "def remove_outliers(values, limit=3.0):\n    n = len(values)\n    if n < 2:\n        return list(values)\n    m = sum(values) / n\n    sd = (sum((v - m) ** 2 for v in values) / (n - 1)) ** 0.5\n    if sd == 0:\n        return list(values)\n    return [v for v in values if abs((v - m) / sd) < limit]\n", "hints": ["Work out mean and sample sd, then keep values with abs(z) < limit."], "topic": "Lab 2"}, {"level": "D6", "id": "fill_gaps", "title": "Fill the gaps", "goal": "Sometimes a reading is missing (<code>None</code>). Write <code>fill_gaps(values)</code>: replace each None with the <em>previous</em> good value (carry forward). A None at the very start stays None.", "starter": "def fill_gaps(values):\n    pass\n", "tests": "t(\"fill_gaps([5, None, None, 7, None])\", lambda: S[\"fill_gaps\"]([5, None, None, 7, None]), [5, 5, 5, 7, 7])\nt(\"fill_gaps([None, 3])\", lambda: S[\"fill_gaps\"]([None, 3]), [None, 3])\nt(\"fill_gaps([])\", lambda: S[\"fill_gaps\"]([]), [])\nt(\"fill_gaps([1, 2])\", lambda: S[\"fill_gaps\"]([1, 2]), [1, 2])", "solution": "def fill_gaps(values):\n    out = []\n    last = None\n    for v in values:\n        if v is None:\n            out.append(last)\n        else:\n            out.append(v)\n            last = v\n    return out\n", "hints": ["Remember the last good value in a variable."], "topic": ""}, {"level": "D6", "id": "arduino_map", "title": "Write Arduino's map()", "goal": "Write <code>arduino_map(x, in_min, in_max, out_min, out_max)</code> exactly like Arduino: <code>(x - in_min) * (out_max - out_min) / (in_max - in_min) + out_min</code>, using <strong>whole-number</strong> maths (truncate toward zero with <code>int()</code>).", "starter": "def arduino_map(x, in_min, in_max, out_min, out_max):\n    pass\n", "tests": "t(\"arduino_map(325, 650, 0, 0, 100)\", lambda: S[\"arduino_map\"](325, 650, 0, 0, 100), 50)\nt(\"arduino_map(442, 650, 0, 0, 100)\", lambda: S[\"arduino_map\"](442, 650, 0, 0, 100), 32)\nt(\"arduino_map(0, 650, 0, 0, 100)\", lambda: S[\"arduino_map\"](0, 650, 0, 0, 100), 100)\nt(\"arduino_map(700, 650, 0, 0, 100)\", lambda: S[\"arduino_map\"](700, 650, 0, 0, 100), -7)\nt(\"arduino_map(5, 0, 10, 0, 100)\", lambda: S[\"arduino_map\"](5, 0, 10, 0, 100), 50)", "solution": "def arduino_map(x, in_min, in_max, out_min, out_max):\n    return int((x - in_min) * (out_max - out_min) / (in_max - in_min) + out_min)\n", "hints": ["Copy the formula and wrap it in int()."], "topic": "Lab 1"}, {"level": "D6", "id": "light_percent", "title": "Raw to light percent", "goal": "Using your <code>arduino_map</code> idea, write <code>light_percent(raw, low=650)</code> that maps raw from <code>low..0</code> to <code>0..100</code> and then <strong>constrains</strong> it to 0–100 (like the sketch).", "starter": "def light_percent(raw, low=650):\n    pass\n", "tests": "t(\"light_percent(688)\", lambda: S[\"light_percent\"](688), 0)\nt(\"light_percent(325)\", lambda: S[\"light_percent\"](325), 50)\nt(\"light_percent(0)\", lambda: S[\"light_percent\"](0), 100)\nt(\"light_percent(442)\", lambda: S[\"light_percent\"](442), 32)\nt(\"light_percent(-50)\", lambda: S[\"light_percent\"](-50), 100)\nt(\"light_percent(400, 800)\", lambda: S[\"light_percent\"](400, 800), 50)", "solution": "def light_percent(raw, low=650):\n    p = int((raw - low) * 100 / (0 - low))\n    return max(0, min(100, p))\n", "hints": ["Map first, then max(0, min(100, p))."], "topic": "Lab 1"}, {"level": "D6", "id": "debounce", "title": "Ignore a single blip", "goal": "Write <code>debounce(readings, need=3)</code>: return the first value that appears <code>need</code> times in a row; if none does, return <code>None</code>.", "starter": "def debounce(readings, need=3):\n    pass\n", "tests": "t(\"debounce(['A', 'B', 'B', 'B', 'A'])\", lambda: S[\"debounce\"](['A', 'B', 'B', 'B', 'A']), 'B')\nt(\"debounce(['A', 'B', 'A', 'B'])\", lambda: S[\"debounce\"](['A', 'B', 'A', 'B']), None)\nt(\"debounce([])\", lambda: S[\"debounce\"]([]), None)\nt(\"debounce(['X', 'X'], 2)\", lambda: S[\"debounce\"](['X', 'X'], 2), 'X')\nt(\"debounce(['A', 'A', 'B', 'B', 'B'], 3)\", lambda: S[\"debounce\"](['A', 'A', 'B', 'B', 'B'], 3), 'B')", "solution": "def debounce(readings, need=3):\n    run = 0\n    last = None\n    for r in readings:\n        run = run + 1 if r == last else 1\n        last = r\n        if run >= need:\n            return r\n    return None\n", "hints": ["Count how long the current run is; reset to 1 when the value changes."], "topic": ""}, {"level": "D6", "id": "group_by", "title": "Group readings", "goal": "Write <code>group_by_condition(rows)</code>: <code>rows</code> is a list of <code>(condition, raw)</code> pairs. Return a dictionary mapping each condition to the list of its raw values.", "starter": "def group_by_condition(rows):\n    pass\n", "tests": "t(\"group_by_condition([('DARK', 688), ('DIM', 400), ('DARK', 690)])\", lambda: S[\"group_by_condition\"]([('DARK', 688), ('DIM', 400), ('DARK', 690)]), {'DARK': [688, 690], 'DIM': [400]})\nt(\"group_by_condition([])\", lambda: S[\"group_by_condition\"]([]), {})", "solution": "def group_by_condition(rows):\n    groups = {}\n    for cond, raw in rows:\n        groups.setdefault(cond, []).append(raw)\n    return groups\n", "hints": ["groups.setdefault(key, []).append(value) is a handy pattern.", "You can unpack pairs in the for line: for cond, raw in rows"], "topic": "Lab 2"}, {"level": "D7", "id": "pipeline", "title": "Clean a whole serial log", "goal": "Write <code>pipeline(lines)</code>. Each line looks like <code>\"Raw ADC: 420  |  Light %: 35%  |  Condition: DIM (...)\"</code>. Parse every line, <strong>skip damaged lines</strong>, drop raw values outside 5–1000, and return the list of <code>(raw, percent, condition)</code> tuples that remain.", "starter": "def pipeline(lines):\n    pass\n", "tests": "lines=[\"Raw ADC: 420  |  Light %: 35%  |  Condition: DIM  (x)\",\"garbled ???\",\"Raw ADC: 4095  |  Light %: 0%  |  Condition: DARK  (x)\",\"Raw ADC: 688  |  Light %: 0%  |  Condition: DARK (x)\",\"Raw ADC: ERR | Light %: 3% | Condition: DARK\",\"Raw ADC: 30  |  Light %: 95%  |  Condition: VERY BRIGHT (x)\"]\nt(\"keeps only good rows\",lambda:S[\"pipeline\"](lines),[(420,35,\"DIM\"),(688,0,\"DARK\"),(30,95,\"VERY BRIGHT\")])\nt(\"empty input\",lambda:S[\"pipeline\"]([]),[])", "solution": "def pipeline(lines):\n    out = []\n    for line in lines:\n        try:\n            parts = line.split(\"|\")\n            raw = int(parts[0].replace(\"Raw ADC:\", \"\").strip())\n            pct = int(parts[1].replace(\"Light %:\", \"\").replace(\"%\", \"\").strip())\n            cond = parts[2].replace(\"Condition:\", \"\").strip().split(\"(\")[0].strip()\n        except (ValueError, IndexError):\n            continue\n        if 5 <= raw <= 1000:\n            out.append((raw, pct, cond))\n    return out\n", "hints": ["Combine your parse_line and filter ideas.", "Use try / except inside the loop and continue on errors."], "topic": "Lab 2"}, {"level": "D7", "id": "summarise", "title": "Summary report", "goal": "Write <code>summarise(raws)</code> returning a dictionary with <code>\"count\"</code>, <code>\"mean\"</code> (2 dp), <code>\"median\"</code>, <code>\"min\"</code> and <code>\"max\"</code>. For an empty list return <code>{\"count\": 0}</code>.", "starter": "def summarise(raws):\n    pass\n", "tests": "t(\"normal\",lambda:S[\"summarise\"]([4,1,3,2]),{\"count\":4,\"mean\":2.5,\"median\":2.5,\"min\":1,\"max\":4})\nt(\"odd count\",lambda:S[\"summarise\"]([9,1,5]),{\"count\":3,\"mean\":5.0,\"median\":5,\"min\":1,\"max\":9})\nt(\"empty\",lambda:S[\"summarise\"]([]),{\"count\":0})", "solution": "def summarise(raws):\n    if not raws:\n        return {\"count\": 0}\n    s = sorted(raws)\n    n = len(s)\n    med = s[n // 2] if n % 2 else (s[n // 2 - 1] + s[n // 2]) / 2\n    return {\"count\": n, \"mean\": round(sum(s) / n, 2), \"median\": med, \"min\": s[0], \"max\": s[-1]}\n", "hints": ["Sort once and reuse it for median, min and max."], "topic": ""}, {"level": "D7", "id": "events", "title": "Count lighting events", "goal": "Write <code>count_events(conditions)</code>: how many times the condition <em>changes</em> from <code>\"DARK\"</code> to something else (the room got lighter). <code>[\"DARK\",\"DARK\",\"DIM\",\"DARK\",\"BRIGHT\"]</code> has 2.", "starter": "def count_events(conditions):\n    pass\n", "tests": "t(\"count_events(['DARK', 'DARK', 'DIM', 'DARK', 'BRIGHT'])\", lambda: S[\"count_events\"](['DARK', 'DARK', 'DIM', 'DARK', 'BRIGHT']), 2)\nt(\"count_events([])\", lambda: S[\"count_events\"]([]), 0)\nt(\"count_events(['DIM', 'DARK'])\", lambda: S[\"count_events\"](['DIM', 'DARK']), 0)\nt(\"count_events(['DARK', 'DIM', 'BRIGHT'])\", lambda: S[\"count_events\"](['DARK', 'DIM', 'BRIGHT']), 1)", "solution": "def count_events(conditions):\n    n = 0\n    for a, b in zip(conditions, conditions[1:]):\n        if a == \"DARK\" and b != \"DARK\":\n            n += 1\n    return n\n", "hints": ["zip(list, list[1:]) gives each neighbouring pair."], "topic": ""}, {"level": "D7", "id": "logger", "title": "A data logger class", "goal": "Write a class <code>Logger</code> with <code>add(value)</code>, <code>mean()</code> (None when empty, else rounded to 2 dp), <code>last(n)</code> (the last n values as a list) and <code>__len__</code> so <code>len(logger)</code> works.", "starter": "class Logger:\n    pass\n", "tests": "lg=S[\"Logger\"]()\nt(\"empty mean\",lambda:lg.mean(),None)\nfor v in (10,20,30,40): lg.add(v)\nt(\"len\",lambda:len(lg),4)\nt(\"mean\",lambda:lg.mean(),25.0)\nt(\"last 2\",lambda:lg.last(2),[30,40])\nt(\"last more than stored\",lambda:lg.last(10),[10,20,30,40])", "solution": "class Logger:\n    def __init__(self):\n        self.values = []\n\n    def add(self, value):\n        self.values.append(value)\n\n    def mean(self):\n        if not self.values:\n            return None\n        return round(sum(self.values) / len(self.values), 2)\n\n    def last(self, n):\n        return self.values[-n:]\n\n    def __len__(self):\n        return len(self.values)\n", "hints": ["Store the list in self.values inside __init__.", "self.values[-n:] gives the last n."], "topic": ""}, {"level": "D8", "id": "day_label", "title": "Name the light band", "goal": "Write <code>label(raw)</code> like the Daylight Tracker sketch: above 500 is <code>\"DARK\"</code>, above 300 is <code>\"DIM\"</code>, above 100 is <code>\"BRIGHT\"</code>, otherwise <code>\"VERY BRIGHT\"</code>.", "starter": "def label(raw):\n    pass\n", "tests": "for raw,want in [(688,\"DARK\"),(501,\"DARK\"),(500,\"DIM\"),(420,\"DIM\"),(300,\"BRIGHT\"),(250,\"BRIGHT\"),(100,\"VERY BRIGHT\"),(34,\"VERY BRIGHT\")]:\n    t(\"label(%d)\"%raw, lambda raw=raw: S[\"label\"](raw), want)", "solution": "def label(raw):\n    if raw > 500:\n        return \"DARK\"\n    elif raw > 300:\n        return \"DIM\"\n    elif raw > 100:\n        return \"BRIGHT\"\n    return \"VERY BRIGHT\"\n", "hints": ["Test the biggest number first, then work down with elif.", "The sketch uses > not >=, so exactly 500 is DIM."], "topic": "CA3 Daylight Tracker"}, {"level": "D8", "id": "day_percent", "title": "Raw value to light %", "goal": "Write <code>light_percent(raw)</code> like <code>map(raw, 650, 0, 0, 100)</code> followed by <code>constrain(..., 0, 100)</code>. Arduino map() works in whole numbers, so use <code>int()</code> on the result.", "starter": "def light_percent(raw):\n    pass\n", "tests": "for raw,want in [(650,0),(325,50),(0,100),(400,38),(688,0),(-20,100),(130,80)]:\n    t(\"light_percent(%d)\"%raw, lambda raw=raw: S[\"light_percent\"](raw), want)", "solution": "def light_percent(raw):\n    value = int((raw - 650) * 100 / (0 - 650))\n    return max(0, min(100, value))\n", "hints": ["map(x, in_min, in_max, out_min, out_max) = (x - in_min) * (out_max - out_min) / (in_max - in_min) + out_min. Here in_min is 650 and in_max is 0.", "Then keep the answer between 0 and 100 with max() and min()."], "topic": "CA3 Daylight Tracker"}, {"level": "D8", "id": "day_lights", "title": "Corridor lights from the percent", "goal": "The B3 extension switches LEDs from the light percent. Write <code>lights(percent, led1=30, led2=60)</code>: below <code>led1</code> return <code>\"RED\"</code> (too dark, lights on), from <code>led1</code> up to below <code>led2</code> return <code>\"YELLOW\"</code>, otherwise <code>\"GREEN\"</code>.", "starter": "def lights(percent, led1=30, led2=60):\n    pass\n", "tests": "t(\"lights(0)\", lambda: S[\"lights\"](0), \"RED\")\nt(\"lights(29)\", lambda: S[\"lights\"](29), \"RED\")\nt(\"lights(30)\", lambda: S[\"lights\"](30), \"YELLOW\")\nt(\"lights(59)\", lambda: S[\"lights\"](59), \"YELLOW\")\nt(\"lights(60)\", lambda: S[\"lights\"](60), \"GREEN\")\nt(\"lights(45, 50, 80)\", lambda: S[\"lights\"](45,50,80), \"RED\")\nt(\"lights(70, 50, 80)\", lambda: S[\"lights\"](70,50,80), \"YELLOW\")", "solution": "def lights(percent, led1=30, led2=60):\n    if percent < led1:\n        return \"RED\"\n    elif percent < led2:\n        return \"YELLOW\"\n    return \"GREEN\"\n", "hints": ["Check the smallest band first: percent < led1.", "The default numbers can be changed when you call the function."], "topic": "CA3 Daylight Tracker"}, {"level": "D8", "id": "day_wrong", "title": "Count the wrong labels (spec 7.1)", "goal": "Write <code>count_wrong(raws, refs, dark=500, dim=300, bright=100)</code>. <code>raws</code> are raw readings from the post and <code>refs</code> are the true labels from the phone app. Label each raw reading with your thresholds and return how many labels do not match.", "starter": "def label(raw, dark=500, dim=300, bright=100):\n    if raw > dark:\n        return \"DARK\"\n    elif raw > dim:\n        return \"DIM\"\n    elif raw > bright:\n        return \"BRIGHT\"\n    return \"VERY BRIGHT\"\n\ndef count_wrong(raws, refs, dark=500, dim=300, bright=100):\n    pass\n", "tests": "raws=[688,467,288,61,357,601]\nrefs=[\"DARK\",\"DIM\",\"BRIGHT\",\"VERY BRIGHT\",\"DIM\",\"DARK\"]\nt(\"kit numbers\", lambda: S[\"count_wrong\"](raws,refs), 0)\nt(\"a bad DARK number\", lambda: S[\"count_wrong\"](raws,refs,700), 2)\nt(\"empty lists\", lambda: S[\"count_wrong\"]([],[]), 0)\nt(\"calibrated numbers\", lambda: S[\"count_wrong\"]([595,214,180,105],[\"DIM\",\"BRIGHT\",\"DIM\",\"VERY BRIGHT\"],620,410,170), 1)", "solution": "def label(raw, dark=500, dim=300, bright=100):\n    if raw > dark:\n        return \"DARK\"\n    elif raw > dim:\n        return \"DIM\"\n    elif raw > bright:\n        return \"BRIGHT\"\n    return \"VERY BRIGHT\"\n\ndef count_wrong(raws, refs, dark=500, dim=300, bright=100):\n    wrong = 0\n    for raw, ref in zip(raws, refs):\n        if label(raw, dark, dim, bright) != ref:\n            wrong += 1\n    return wrong\n", "hints": ["zip(raws, refs) gives pairs, one raw reading with its true label.", "Add one to wrong each time label(...) is not equal to ref."], "topic": "CA3 Daylight Tracker"}, {"level": "D8", "id": "day_midpoint", "title": "Threshold halfway between two conditions", "goal": "Write <code>midpoint(a, b)</code>: <code>a</code> and <code>b</code> are lists of raw readings from two conditions. Return the whole number halfway between their <strong>medians</strong>. Return <code>None</code> if either list is empty.", "starter": "import statistics\n\ndef midpoint(a, b):\n    pass\n", "tests": "t(\"DARK 688s and DIM 440s\", lambda: S[\"midpoint\"]([688,690,686],[440,430,450]), 564)\nt(\"odd lists\", lambda: S[\"midpoint\"]([600,610,620],[400,410,420]), 510)\nt(\"median ignores a spike\", lambda: S[\"midpoint\"]([688,688,688,150],[430,440,450]), 564)\nt(\"empty a\", lambda: S[\"midpoint\"]([],[1,2]), None)\nt(\"empty b\", lambda: S[\"midpoint\"]([1,2],[]), None)", "solution": "import statistics\n\ndef midpoint(a, b):\n    if not a or not b:\n        return None\n    return round((statistics.median(a) + statistics.median(b)) / 2)\n", "hints": ["statistics.median(list) gives the middle value, so one spike does not move it.", "round((median_a + median_b) / 2)"], "topic": "CA3 Daylight Tracker"}, {"level": "D8", "id": "day_smooth", "title": "Smooth the day with a moving average", "goal": "Write <code>moving_avg(values, n=5)</code>: for each position, average the last <code>n</code> values (use fewer at the start), rounded to 1 decimal place. Return a list as long as <code>values</code>.", "starter": "def moving_avg(values, n=5):\n    pass\n", "tests": "t(\"short list\", lambda: S[\"moving_avg\"]([10,20,30], 5), [10.0,15.0,20.0])\nt(\"window of 3\", lambda: S[\"moving_avg\"]([2,4,6,8], 3), [2.0,3.0,4.0,6.0])\nt(\"one spike is smoothed\", lambda: S[\"moving_avg\"]([688,688,688,688,442,690], 5)[4], 638.8)\nt(\"empty\", lambda: S[\"moving_avg\"]([]), [])", "solution": "def moving_avg(values, n=5):\n    out = []\n    for i in range(len(values)):\n        window = values[max(0, i - n + 1): i + 1]\n        out.append(round(sum(window) / len(window), 1))\n    return out\n", "hints": ["The window for position i is values[max(0, i - n + 1): i + 1].", "Average = sum(window) / len(window)."], "topic": "CA3 Daylight Tracker"}, {"level": "D8", "id": "day_hours", "title": "How many hours of daylight?", "goal": "The post takes 144 readings in 16 hours. Write <code>light_hours(labels)</code>: count the labels that are not <code>\"DARK\"</code> and return the hours, <code>count * 16 / 144</code>, rounded to 1 decimal place.", "starter": "def light_hours(labels):\n    pass\n", "tests": "t(\"all dark\", lambda: S[\"light_hours\"]([\"DARK\"]*144), 0.0)\nt(\"all light\", lambda: S[\"light_hours\"]([\"BRIGHT\"]*144), 16.0)\nt(\"mixed\", lambda: S[\"light_hours\"]([\"DARK\"]*45+[\"DIM\"]*9+[\"BRIGHT\"]*90), 11.0)\nt(\"empty\", lambda: S[\"light_hours\"]([]), 0.0)", "solution": "def light_hours(labels):\n    light = 0\n    for lab in labels:\n        if lab != \"DARK\":\n            light += 1\n    return round(light * 16 / 144, 1)\n", "hints": ["Count with a loop and an if: lab != \"DARK\".", "One reading is 16 / 144 of an hour."], "topic": "CA3 Daylight Tracker"}, {"level": "D8", "id": "day_firstlast", "title": "When did the light start and end?", "goal": "Write <code>first_last(rows)</code>. Each row is <code>(\"2026-10-14 07:00:00\", \"DIM\")</code>. Return the tuple <code>(first, last)</code> of the <code>HH:MM</code> times of the first and last row that is not <code>\"DARK\"</code>. Return <code>None</code> if the whole day is DARK.", "starter": "def first_last(rows):\n    pass\n", "tests": "rows=[(\"2026-10-14 05:00:00\",\"DARK\"),(\"2026-10-14 07:00:00\",\"DIM\"),(\"2026-10-14 12:20:00\",\"BRIGHT\"),(\"2026-10-14 17:00:00\",\"DIM\"),(\"2026-10-14 19:00:00\",\"DARK\")]\nt(\"first and last light\", lambda: S[\"first_last\"](rows), (\"07:00\",\"17:00\"))\nt(\"all dark\", lambda: S[\"first_last\"]([(\"2026-10-14 05:00:00\",\"DARK\")]), None)\nt(\"one light row\", lambda: S[\"first_last\"]([(\"2026-10-14 05:00:00\",\"DARK\"),(\"2026-10-14 09:30:00\",\"BRIGHT\")]), (\"09:30\",\"09:30\"))", "solution": "def first_last(rows):\n    light = [r for r in rows if r[1] != \"DARK\"]\n    if not light:\n        return None\n    return light[0][0][11:16], light[-1][0][11:16]\n", "hints": ["Build a list of the rows that are not DARK first.", "The time HH:MM is the slice [11:16] of the timestamp text."], "topic": "CA3 Daylight Tracker"}, {"level": "D8", "id": "day_energy", "title": "Energy and cost saved (mini project)", "goal": "A corridor has 20 lamps of 36 W. Write <code>saving(light_hours, lamps=20, watts=36, aed_per_kwh=0.35)</code> that returns a dictionary with <code>\"kwh\"</code> (lamps × watts × hours ÷ 1000) and <code>\"aed\"</code> (kwh × rate), both rounded to 1 decimal place. The 0.35 rate is an example for practice, not a tariff.", "starter": "def saving(light_hours, lamps=20, watts=36, aed_per_kwh=0.35):\n    pass\n", "tests": "t(\"9.7 hours\", lambda: S[\"saving\"](9.7), {\"kwh\":7.0,\"aed\":2.4})\nt(\"0 hours\", lambda: S[\"saving\"](0), {\"kwh\":0.0,\"aed\":0.0})\nt(\"10 lamps\", lambda: S[\"saving\"](10, 10), {\"kwh\":3.6,\"aed\":1.3})\nt(\"other rate\", lambda: S[\"saving\"](10, 20, 36, 0.5), {\"kwh\":7.2,\"aed\":3.6})", "solution": "def saving(light_hours, lamps=20, watts=36, aed_per_kwh=0.35):\n    kwh = lamps * watts * light_hours / 1000\n    return {\"kwh\": round(kwh, 1), \"aed\": round(kwh * aed_per_kwh, 1)}\n", "hints": ["kwh = lamps * watts * light_hours / 1000.", "Use the unrounded kwh to find the cost, then round both answers."], "topic": "CA3 Daylight Tracker"}]};